{"file_path":"/work/safety_evals/loader.py","content":""""AI alignment evaluation: monitor flag statistics over model transcripts."""



def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped:
            continue
        if line.lstrip().startswith("#"):
            continue

        fields = line.split(",")
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected 3 fields")

        id_, day_text, flagged_text = (field.strip() for field in fields)

        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc

        if flagged_text == "1":
            flagged = True
        elif flagged_text == "0":
            flagged = False
        elif flagged_text == "":
            flagged = None
        else:
            raise ValueError(f"line {line_number}: invalid flagged value")

        out.append({"id": id_, "day": day, "flagged": flagged})
    return out



def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    seen = {}
    for event in events:
        seen[event["id"]] = event
    return sorted(seen.values(), key=lambda event: (event["day"], event["id"]))



def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        if event.get("flagged") is True and start_day <= event["day"] <= end_day:
            counts[event["day"] - start_day] += 1
    return counts
